CREATE TABLE rt_orders (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), order_no varchar(48) NOT NULL UNIQUE, channel varchar(8) NOT NULL CHECK(channel IN ('b2b','b2c')), company_id uuid REFERENCES rt_companies(id) ON DELETE RESTRICT, customer_user_id bigint NOT NULL REFERENCES users(id) ON DELETE RESTRICT, created_by bigint NOT NULL REFERENCES users(id) ON DELETE RESTRICT, status varchar(32) NOT NULL DEFAULT 'draft', currency char(3) NOT NULL REFERENCES rt_currencies(code), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CHECK((channel='b2b' AND company_id IS NOT NULL) OR (channel='b2c' AND company_id IS NULL)));
CREATE INDEX rt_orders_company_idx ON rt_orders(company_id,created_at DESC);
CREATE TABLE rt_bookings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), order_id uuid NOT NULL REFERENCES rt_orders(id) ON DELETE RESTRICT, booking_no varchar(48) NOT NULL UNIQUE, service_type varchar(32) NOT NULL CHECK(service_type IN ('hotel','transport','visa','flight','apartment','event','other')), channel varchar(8) NOT NULL CHECK(channel IN ('b2b','b2c')), company_id uuid REFERENCES rt_companies(id) ON DELETE RESTRICT, customer_user_id bigint NOT NULL REFERENCES users(id) ON DELETE RESTRICT, supplier_id uuid REFERENCES rt_suppliers(id) ON DELETE RESTRICT, status varchar(32) NOT NULL DEFAULT 'draft', currency char(3) NOT NULL REFERENCES rt_currencies(code), approved_total numeric(20,6) CHECK(approved_total>=0), confirmed_at timestamptz, version integer NOT NULL DEFAULT 1 CHECK(version>0), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CHECK((channel='b2b' AND company_id IS NOT NULL) OR (channel='b2c' AND company_id IS NULL)));
CREATE INDEX rt_bookings_order_idx ON rt_bookings(order_id); CREATE INDEX rt_bookings_company_status_idx ON rt_bookings(company_id,status); CREATE INDEX rt_bookings_customer_idx ON rt_bookings(customer_user_id);
CREATE TABLE rt_booking_guests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), booking_id uuid NOT NULL REFERENCES rt_bookings(id) ON DELETE RESTRICT, first_name varchar(150) NOT NULL, last_name varchar(150) NOT NULL, guest_type varchar(24) NOT NULL DEFAULT 'adult', date_of_birth date, nationality_code char(2), is_lead boolean NOT NULL DEFAULT false);
CREATE TABLE rt_hotel_booking_details (booking_id uuid PRIMARY KEY REFERENCES rt_bookings(id) ON DELETE RESTRICT, hotel_id uuid REFERENCES rt_hotels(id) ON DELETE RESTRICT, check_in date NOT NULL, check_out date NOT NULL, rooms_count integer NOT NULL CHECK(rooms_count>0), supplier_offer_ref varchar(255), CHECK(check_out>check_in));
CREATE TABLE rt_transport_booking_details (booking_id uuid PRIMARY KEY REFERENCES rt_bookings(id) ON DELETE RESTRICT, provider_id uuid REFERENCES rt_transport_providers(id) ON DELETE RESTRICT, pickup_at timestamptz NOT NULL, pickup_address text NOT NULL, dropoff_address text, service_mode varchar(32) NOT NULL, passengers integer NOT NULL CHECK(passengers>0));
CREATE TABLE rt_service_booking_details (booking_id uuid PRIMARY KEY REFERENCES rt_bookings(id) ON DELETE RESTRICT, service_type varchar(32) NOT NULL CHECK(service_type IN ('visa','flight','apartment','event','other')), description text NOT NULL, requested_start_at timestamptz, requested_end_at timestamptz);
CREATE TABLE rt_transport_assignments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), booking_id uuid NOT NULL REFERENCES rt_transport_booking_details(booking_id) ON DELETE RESTRICT, vehicle_id uuid NOT NULL REFERENCES rt_vehicles(id) ON DELETE RESTRICT, driver_id uuid REFERENCES rt_drivers(id) ON DELETE RESTRICT, starts_at timestamptz NOT NULL, ends_at timestamptz NOT NULL, status varchar(24) NOT NULL DEFAULT 'proposed', CHECK(ends_at>starts_at));
CREATE TABLE rt_booking_price_snapshots (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), booking_id uuid NOT NULL REFERENCES rt_bookings(id) ON DELETE RESTRICT, version integer NOT NULL CHECK(version>0), currency char(3) NOT NULL REFERENCES rt_currencies(code), supplier_cost numeric(20,6), admin_markup numeric(20,6), company_markup numeric(20,6), discount_amount numeric(20,6), fee_amount numeric(20,6), tax_amount numeric(20,6), customer_total numeric(20,6) NOT NULL CHECK(customer_total>=0), pricing_policy_id uuid REFERENCES rt_pricing_policies(id) ON DELETE RESTRICT, approved_by bigint REFERENCES users(id) ON DELETE RESTRICT, approved_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(booking_id,version));
CREATE TABLE rt_booking_fx_snapshots (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), price_snapshot_id uuid NOT NULL REFERENCES rt_booking_price_snapshots(id) ON DELETE RESTRICT, fx_rate_id uuid REFERENCES rt_fx_rates(id) ON DELETE RESTRICT, base_currency char(3) NOT NULL REFERENCES rt_currencies(code), quote_currency char(3) NOT NULL REFERENCES rt_currencies(code), reference_rate numeric(24,12), commercial_rate numeric(24,12) NOT NULL CHECK(commercial_rate>0), rate_source varchar(120) NOT NULL, rate_version varchar(64), observed_at timestamptz NOT NULL, expires_at timestamptz, UNIQUE(price_snapshot_id,base_currency,quote_currency));
CREATE TABLE rt_supplier_booking_attempts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), booking_id uuid NOT NULL REFERENCES rt_bookings(id) ON DELETE RESTRICT, supplier_id uuid NOT NULL REFERENCES rt_suppliers(id) ON DELETE RESTRICT, operation varchar(32) NOT NULL, attempt_no integer NOT NULL CHECK(attempt_no>0), state varchar(32) NOT NULL DEFAULT 'created', request_key varchar(160), started_at timestamptz NOT NULL DEFAULT now(), finished_at timestamptz, last_error_code varchar(120), UNIQUE(booking_id,operation,attempt_no));
CREATE TABLE rt_supplier_external_refs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), attempt_id uuid NOT NULL REFERENCES rt_supplier_booking_attempts(id) ON DELETE RESTRICT, supplier_id uuid NOT NULL REFERENCES rt_suppliers(id) ON DELETE RESTRICT, reference_kind varchar(40) NOT NULL, reference_value varchar(255) NOT NULL, UNIQUE(supplier_id,reference_kind,reference_value));
CREATE TABLE rt_idempotency_keys (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), actor_user_id bigint REFERENCES users(id) ON DELETE RESTRICT, scope varchar(120) NOT NULL, key_hash char(64) NOT NULL, request_hash char(64) NOT NULL, state varchar(24) NOT NULL DEFAULT 'processing', response_code integer, response_body text, expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(scope,key_hash));
CREATE TABLE rt_webhook_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), source varchar(80) NOT NULL, provider_event_id varchar(255) NOT NULL, payload_hash char(64) NOT NULL, signature_verified boolean NOT NULL DEFAULT false, status varchar(24) NOT NULL DEFAULT 'received', received_at timestamptz NOT NULL DEFAULT now(), processed_at timestamptz, UNIQUE(source,provider_event_id));
CREATE TABLE rt_outbox_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), aggregate_type varchar(80) NOT NULL, aggregate_id uuid NOT NULL, event_type varchar(120) NOT NULL, payload text NOT NULL, state varchar(24) NOT NULL DEFAULT 'pending', attempts integer NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now(), processed_at timestamptz);
CREATE INDEX rt_outbox_pending_idx ON rt_outbox_events(state,created_at);
CREATE TABLE rt_reconciliation_cases (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), booking_id uuid REFERENCES rt_bookings(id) ON DELETE RESTRICT, supplier_attempt_id uuid REFERENCES rt_supplier_booking_attempts(id) ON DELETE RESTRICT, payment_intent_id uuid, case_type varchar(48) NOT NULL, status varchar(24) NOT NULL DEFAULT 'open', assigned_to bigint REFERENCES users(id) ON DELETE RESTRICT, notes text, created_at timestamptz NOT NULL DEFAULT now(), resolved_at timestamptz);
